if config then config.dimensions = 2 end

growthClusterCount = 0
function growthCluster(r, ncells, reverse)
   growthClusterCount = growthClusterCount + 1
   local name = string.format("growthCluster%d", growthClusterCount)
   local R = r^ncells
   _G[name] = function(t)
      if reverse then t = 1.0 - t end
      local x = (R^t - 1.0)/(R - 1.0)
      if reverse then x = 1.0 - x end
      return x
   end
   return LuaFnClustering:new{luaFnName=name}
end

-- Vertex positions given as a table (0..1), linear in between.
function tableCluster(x)
   growthClusterCount = growthClusterCount + 1
   local name = string.format("growthCluster%d", growthClusterCount)
   local n = #x - 1
   _G[name] = function(t)
      local u = t*n
      local k = math.floor(u)
      if k >= n then return x[n+1] end
      if k < 0 then return x[1] end
      return x[k+1] + (u - k)*(x[k+2] - x[k+1])
   end
   return LuaFnClustering:new{luaFnName=name}
end

